// Pytania w formie stanowisk, część 2 (30 pytań, mniej więcej po 3 na każdą oś).
// Format jak w positions.js. Stanowiska to typowe postawy ok. 2025–2026, nie poglądy konkretnych osób.
window.SZ = window.SZ || {};

SZ.QUESTIONS = (SZ.QUESTIONS || []).concat([
  // ───────── GOSPODARKA ─────────
  { id: 'x_health', type: 'positions',
    text: { pl: 'Jak powinna być zorganizowana opieka zdrowotna?', en: 'How should healthcare be organised?' },
    what: { pl: 'Kto płaci za leczenie i kto je prowadzi: państwo, prywatni ubezpieczyciele czy jedno i drugie.', en: 'Who pays for treatment and who provides it: the state, private insurers, or both.' },
    options: [
      { camp: 'left', effects: { econ: -0.9 },
        text: { pl: 'W pełni publiczna i darmowa, z podatków, bez prywatnych dopłat', en: 'Fully public and free, paid from taxes, with no private top-ups' },
        why: { pl: 'Zdrowie nie może zależeć od portfela; wspólny system jest tańszy niż wiele prywatnych.', en: 'Health must not depend on your wallet; one shared system costs less than many private ones.' },
        example: { pl: 'Wielka Brytania — NHS od 1948 r. leczy wszystkich za darmo, finansowany z podatków.', en: 'The United Kingdom — since 1948 the NHS has treated everyone for free, funded from taxes.' },
        wiki: { pl: 'National Health Service', en: 'National Health Service' } },
      { camp: 'center', effects: { econ: -0.3 },
        text: { pl: 'Publiczna podstawa dla każdego plus dodatkowe ubezpieczenia i współpraca z prywatnymi placówkami', en: 'A public base for everyone plus supplementary insurance and cooperation with private clinics' },
        why: { pl: 'Publiczny system gwarantuje leczenie, a prywatne placówki skracają kolejki.', en: 'The public system guarantees care, while private providers shorten waiting lists.' },
        example: { pl: 'Francja — powszechne ubezpieczenie publiczne uzupełnia dodatkowe ubezpieczenie, które ma większość mieszkańców.', en: 'France — universal public insurance is topped up by supplementary cover that most residents have.' },
        wiki: { pl: 'Narodowy Fundusz Zdrowia', en: 'Health care in France' } },
      { camp: 'right', effects: { econ: 0.8 },
        text: { pl: 'Obowiązkowe ubezpieczenie, ale u konkurujących ze sobą ubezpieczycieli', en: 'Compulsory insurance, but with insurers competing against each other' },
        why: { pl: 'Konkurencja wymusza jakość i oszczędność, a pacjent może zmienić ubezpieczyciela, gdy jest niezadowolony.', en: 'Competition forces quality and savings, and patients can switch insurer when unhappy.' },
        example: { pl: 'Szwajcaria i Holandia — każdy musi się ubezpieczyć, ale sam wybiera prywatnego ubezpieczyciela.', en: 'Switzerland and the Netherlands — everyone must be insured but chooses their own private insurer.' },
        wiki: { pl: 'Ubezpieczenie zdrowotne', en: 'Healthcare in Switzerland' } }
    ] },

  { id: 'x_minwage', type: 'positions',
    text: { pl: 'Co z płacą minimalną?', en: 'What about the minimum wage?' },
    what: { pl: 'Najniższa pensja, jaką wolno zapłacić za pełny etat. W Polsce ustala ją co roku rząd.', en: 'The lowest pay allowed for full-time work. In Poland the government sets it every year.' },
    options: [
      { camp: 'left', effects: { econ: -0.9 },
        text: { pl: 'Podnosić szybko, do co najmniej 60% przeciętnej pensji', en: 'Raise it quickly, to at least 60% of the average wage' },
        why: { pl: 'Praca na pełny etat powinna pozwalać godnie żyć; wyższe płace zwiększają też popyt w gospodarce.', en: 'Full-time work should allow a decent life; higher pay also boosts demand in the economy.' },
        example: { pl: 'Unijna dyrektywa z 2022 r. wskazuje 60% mediany płac jako punkt odniesienia.', en: 'The 2022 EU directive names 60% of the median wage as a benchmark.' },
        wiki: { pl: 'Płaca minimalna', en: 'Minimum wage' } },
      { camp: 'center', effects: { econ: 0 },
        text: { pl: 'Podnosić według stałego wzoru, z inflacją i wzrostem gospodarki', en: 'Raise it by a fixed formula, with inflation and economic growth' },
        why: { pl: 'Przewidywalne podwyżki chronią pracowników, a firmy mogą się do nich przygotować.', en: 'Predictable rises protect workers, and businesses can plan for them.' },
        example: { pl: 'Niemcy — wysokość płacy minimalnej proponuje komisja pracodawców, związków i ekspertów.', en: 'Germany — the minimum wage is proposed by a commission of employers, unions and experts.' },
        wiki: { pl: 'Płaca minimalna', en: 'Minimum wage in Germany' } },
      { camp: 'right', effects: { econ: 0.9 },
        text: { pl: 'Nie podnosić jej odgórnie, a najlepiej zlikwidować — niech płace ustala rynek', en: 'Do not raise it by decree, ideally abolish it — let the market set wages' },
        why: { pl: 'Zbyt wysoka płaca minimalna wypycha do szarej strefy lub na bezrobocie najsłabszych: młodych i bez doświadczenia.', en: 'Too high a minimum wage pushes the weakest — the young and inexperienced — into the grey economy or unemployment.' },
        example: { pl: 'Singapur nie ma powszechnej płacy minimalnej i ma bardzo niskie bezrobocie.', en: 'Singapore has no universal minimum wage and very low unemployment.' },
        wiki: { pl: 'Szara strefa', en: 'Informal economy' } }
    ] },

  { id: 'x_stateco', type: 'positions',
    text: { pl: 'Kto powinien być właścicielem firm energetycznych, paliwowych i kolei?', en: 'Who should own energy and fuel companies and the railways?' },
    what: { pl: 'Spór o to, czy strategiczne firmy mają należeć do państwa, do prywatnych inwestorów, czy do obu.', en: 'Whether strategic companies should belong to the state, private investors, or both.' },
    options: [
      { camp: 'left', effects: { econ: -1 },
        text: { pl: 'W całości państwo — zyski mają służyć wszystkim, a nie akcjonariuszom', en: 'Entirely the state — profits should serve everyone, not shareholders' },
        why: { pl: 'Prąd, paliwo i transport to podstawowe potrzeby; państwo może trzymać niskie ceny i inwestować w regiony.', en: 'Power, fuel and transport are basic needs; the state can keep prices low and invest in the regions.' },
        example: { pl: 'Francja w 2023 r. odkupiła wszystkie akcje koncernu energetycznego EDF.', en: 'In 2023 France bought back all the shares of the energy company EDF.' },
        wiki: { pl: 'Nacjonalizacja', en: 'Nationalization' } },
      { camp: 'center', effects: { econ: -0.1 },
        text: { pl: 'Państwo ma pakiet kontrolny, ale spółki są na giełdzie i działają jak firmy', en: 'The state holds a controlling stake, but the companies are listed and run as businesses' },
        why: { pl: 'Państwo pilnuje bezpieczeństwa, a giełda i prywatni akcjonariusze wymuszają przejrzystość.', en: 'The state safeguards security, while the stock market and private shareholders enforce transparency.' },
        example: { pl: 'Norwegia — państwo ma większość akcji Equinor, a resztą handluje się na giełdzie.', en: 'Norway — the state owns most of Equinor, and the rest is traded on the stock exchange.' },
        wiki: { pl: 'Skarb Państwa', en: 'Equinor' } },
      { camp: 'right_cons', effects: { econ: 0, world: 0.6 },
        text: { pl: 'Mają zostać w polskich rękach — państwowych albo polskiego kapitału', en: 'They must stay in Polish hands — the state or Polish capital' },
        why: { pl: 'Kto kontroluje energię, ten kontroluje kraj; obcy właściciel w kryzysie zadba o swoich.', en: 'Whoever controls energy controls the country; in a crisis a foreign owner will look after its own.' },
        example: { pl: 'Polska po 2015 r. „repolonizowała” część banków i energetyki, odkupując je od zagranicznych właścicieli.', en: 'After 2015 Poland "re-Polonised" some banks and energy firms by buying them from foreign owners.' },
        wiki: { pl: 'Patriotyzm gospodarczy', en: 'Economic nationalism' } },
      { camp: 'right_free', effects: { econ: 1 },
        text: { pl: 'Sprywatyzować — państwo jest złym właścicielem', en: 'Privatise — the state is a bad owner' },
        why: { pl: 'Państwowe spółki służą politykom za synekury, a konkurencja daje lepsze usługi i niższe ceny.', en: 'State companies become jobs for politicians\' friends, while competition brings better service and lower prices.' },
        example: { pl: 'Wielka Brytania w latach 80. sprywatyzowała m.in. British Telecom i British Gas.', en: 'In the 1980s the UK privatised British Telecom and British Gas, among others.' },
        wiki: { pl: 'Prywatyzacja', en: 'Privatization' } }
    ] },

  // ───────── WŁADZA ─────────
  { id: 'x_courts', type: 'positions',
    text: { pl: 'Kto powinien wybierać sędziów?', en: 'Who should choose judges?' },
    what: { pl: 'W Polsce od 2017 r. trwa spór o Krajową Radę Sądownictwa, Trybunał Konstytucyjny i to, ile wpływu na sądy mają politycy.', en: 'Since 2017 Poland has been arguing about the National Council of the Judiciary, the Constitutional Tribunal, and how much influence politicians have over courts.' },
    options: [
      { camp: 'left', effects: { power: -0.9 },
        text: { pl: 'Głównie sami sędziowie — politycy powinni trzymać się od sądów z daleka', en: 'Mainly judges themselves — politicians should keep away from the courts' },
        why: { pl: 'Sąd musi móc orzec przeciw rządowi; gdy sędziów wybiera władza, przestaje być bezstronny.', en: 'A court must be able to rule against the government; if those in power pick judges, it stops being impartial.' },
        example: { pl: 'Trybunał Sprawiedliwości UE orzekał, że polska reforma KRS z 2017 r. narusza niezależność sądów.', en: 'The EU Court of Justice ruled that Poland\'s 2017 reform of the judicial council violated judicial independence.' },
        wiki: { pl: 'Trójpodział władzy', en: 'Separation of powers' } },
      { camp: 'center', effects: { power: -0.5 },
        text: { pl: 'Parlament, ale dużą większością głosów, żeby kandydata musiała poprzeć też opozycja', en: 'Parliament, but by a large majority, so the opposition must back the candidate too' },
        why: { pl: 'Sędziowie mają mandat demokratyczny, a wymóg porozumienia chroni przed przejęciem sądów przez jedną partię.', en: 'Judges get a democratic mandate, and the need for consensus stops one party from capturing the courts.' },
        example: { pl: 'Niemcy — sędziów Trybunału Konstytucyjnego wybiera Bundestag i Bundesrat większością 2/3.', en: 'Germany — constitutional judges are elected by the Bundestag and Bundesrat with a two-thirds majority.' },
        wiki: { pl: 'Federalny Trybunał Konstytucyjny', en: 'Federal Constitutional Court' } },
      { camp: 'right', effects: { power: 0.4 },
        text: { pl: 'Większy wpływ wybranych przez naród polityków — sędziowie nie mogą być zamkniętą kastą', en: 'More say for politicians elected by the people — judges must not be a closed caste' },
        why: { pl: 'Sędziowie też powinni podlegać demokratycznej kontroli, a środowisko samo się nie oczyści.', en: 'Judges too should be under democratic control, and the profession will not clean itself up.' },
        example: { pl: 'Reforma z 2017 r. dała Sejmowi wybór 15 sędziów-członków KRS.', en: 'The 2017 reform gave the Sejm the right to pick the 15 judge members of the judicial council.' },
        wiki: { pl: 'Krajowa Rada Sądownictwa', en: 'National Council of the Judiciary (Poland)' } }
    ] },

  { id: 'x_pubmedia', type: 'positions',
    text: { pl: 'Jakie powinny być media publiczne (TVP, Polskie Radio)?', en: 'What should public media (TVP, Polish Radio) be like?' },
    what: { pl: 'Media finansowane z publicznych pieniędzy: kto nimi rządzi i czemu mają służyć.', en: 'Media paid for with public money: who runs them and what they are for.' },
    options: [
      { camp: 'left', effects: { power: -0.8, econ: -0.3 },
        text: { pl: 'Niezależne od rządu, z własnym abonamentem i radą wybieraną poza partiami', en: 'Independent of the government, with their own licence fee and a board chosen outside the parties' },
        why: { pl: 'Media publiczne mają patrzeć władzy na ręce, a nie być jej tubą — niezależnie, kto rządzi.', en: 'Public media should hold power to account, not be its mouthpiece — whoever is in government.' },
        example: { pl: 'BBC — finansowane z abonamentu i znane z tego, że krytykuje każdy rząd.', en: 'The BBC — funded by a licence fee and known for criticising every government.' },
        wiki: { pl: 'BBC', en: 'BBC' } },
      { camp: 'center', effects: { power: -0.4 },
        text: { pl: 'Publiczne, ale rzetelne i bezstronne — mniej polityki, więcej kultury i edukacji', en: 'Public, but reliable and impartial — less politics, more culture and education' },
        why: { pl: 'Media publiczne są potrzebne tam, gdzie komercyjne się nie opłacają: teatr, nauka, regiony.', en: 'Public media are needed where commercial ones do not pay off: theatre, science, the regions.' },
        example: { pl: 'Niemieckie ARD i ZDF — spory polityczne o nie trwają, ale zarządzają nimi rady z przedstawicielami społeczeństwa.', en: 'Germany\'s ARD and ZDF — still politically disputed, but run by boards with representatives of society.' },
        wiki: { pl: 'Telewizja Polska', en: 'Telewizja Polska' } },
      { camp: 'right_cons', effects: { soc: 0.6, power: 0.3 },
        text: { pl: 'Powinny promować polską historię, kulturę i tradycyjne wartości', en: 'They should promote Polish history, culture and traditional values' },
        why: { pl: 'Media prywatne często należą do zagranicznych właścicieli; publiczne mają dbać o wspólnotę narodową.', en: 'Private media often have foreign owners; public media should look after the national community.' },
        example: { pl: 'Polska ustawa o radiofonii i telewizji nakazuje mediom publicznym respektować chrześcijański system wartości.', en: 'Poland\'s broadcasting act requires public media to respect Christian values.' },
        wiki: { pl: 'Media publiczne', en: 'Public broadcasting' } },
      { camp: 'right_free', effects: { econ: 0.8, power: -0.5 },
        text: { pl: 'Zlikwidować albo sprzedać — państwo nie powinno mieć własnej telewizji', en: 'Abolish or sell them — the state should not have its own TV station' },
        why: { pl: 'Każda władza będzie je przejmować dla siebie; podatnik nie powinien za to płacić.', en: 'Every government will take them over for itself; taxpayers should not pay for that.' },
        example: { pl: 'Argentyna — prezydent Milei w 2024 r. zapowiedział prywatyzację mediów publicznych.', en: 'Argentina — in 2024 President Milei announced plans to privatise public media.' },
        wiki: { pl: 'Prywatyzacja', en: 'Privatization' } }
    ] },

  { id: 'x_referendum', type: 'positions',
    text: { pl: 'Jak obywatele powinni decydować o ważnych sprawach?', en: 'How should citizens decide on important matters?' },
    what: { pl: 'Czy wystarczą wybory co kilka lat, czy ludzie powinni częściej głosować bezpośrednio.', en: 'Whether elections every few years are enough, or people should vote directly more often.' },
    options: [
      { camp: 'left', effects: { power: -0.7, local: -0.3 },
        text: { pl: 'Zgromadzenia obywatelskie: wylosowani mieszkańcy rozważają sprawę z ekspertami i rekomendują decyzję', en: 'Citizens\' assemblies: randomly chosen residents study an issue with experts and recommend a decision' },
        why: { pl: 'Zwykli ludzie, dobrze poinformowani, potrafią się porozumieć tam, gdzie politycy się kłócą.', en: 'Ordinary people, well informed, can agree where politicians keep fighting.' },
        example: { pl: 'Irlandia — zgromadzenia obywateli przygotowały referenda o małżeństwach (2015) i aborcji (2018).', en: 'Ireland — citizens\' assemblies paved the way for referendums on marriage (2015) and abortion (2018).' },
        wiki: { pl: 'Panel obywatelski', en: 'Citizens\' assembly' } },
      { camp: 'center', effects: { power: -0.2 },
        text: { pl: 'Głównie przez wybranych posłów; referendum tylko w sprawach wyjątkowych', en: 'Mainly through elected MPs; referendums only on exceptional issues' },
        why: { pl: 'Skomplikowane ustawy wymagają wiedzy i kompromisu, a referenda łatwo zamienić w plebiscyt emocji.', en: 'Complex laws need expertise and compromise, and referendums easily become contests of emotion.' },
        example: { pl: 'W Polsce referendum jest wiążące tylko przy frekwencji powyżej 50% — dotąd udało się to raz, w 2003 r. (wejście do UE).', en: 'In Poland a referendum is binding only with turnout above 50% — achieved just once so far, in 2003 (EU accession).' },
        wiki: { pl: 'Demokracja przedstawicielska', en: 'Representative democracy' } },
      { camp: 'right', effects: { power: -0.6, world: 0.3 },
        text: { pl: 'Wiążące referenda, gdy zbierze się dość podpisów — jak w Szwajcarii', en: 'Binding referendums when enough signatures are collected — as in Switzerland' },
        why: { pl: 'Naród jest suwerenem i powinien móc zatrzymać polityków, którzy decydują wbrew niemu.', en: 'The nation is sovereign and should be able to stop politicians who act against its will.' },
        example: { pl: 'Szwajcaria — 100 tys. podpisów wystarcza, by obywatele zagłosowali nad zmianą konstytucji.', en: 'Switzerland — 100,000 signatures are enough to put a constitutional change to a popular vote.' },
        wiki: { pl: 'Demokracja bezpośrednia', en: 'Direct democracy' } }
    ] },

  // ───────── OBYCZAJE ─────────
  { id: 'x_abortion', type: 'positions',
    text: { pl: 'Kiedy aborcja powinna być legalna?', en: 'When should abortion be legal?' },
    what: { pl: 'Od 2021 r. w Polsce aborcja jest legalna tylko przy zagrożeniu życia lub zdrowia kobiety albo gdy ciąża jest skutkiem przestępstwa.', en: 'Since 2021 abortion in Poland has been legal only if the woman\'s life or health is at risk or the pregnancy results from a crime.' },
    options: [
      { camp: 'left', effects: { soc: -1, relig: -0.4 },
        text: { pl: 'Na życzenie kobiety do 12. tygodnia ciąży', en: 'On request up to the 12th week of pregnancy' },
        why: { pl: 'To kobieta ponosi skutki ciąży i to ona powinna decydować; zakazy nie zmniejszają liczby aborcji, tylko przenoszą je za granicę.', en: 'The woman bears the consequences of pregnancy and should decide; bans do not reduce abortions, they move them abroad.' },
        example: { pl: 'Francja w 2024 r. wpisała wolność przerywania ciąży do konstytucji.', en: 'In 2024 France wrote the freedom to have an abortion into its constitution.' },
        wiki: { pl: 'Aborcja', en: 'Abortion law' } },
      { camp: 'center', effects: { soc: 0 },
        text: { pl: 'Powrót do kompromisu z 1993 r. albo referendum w tej sprawie', en: 'Return to the 1993 compromise, or hold a referendum on it' },
        why: { pl: 'Spór dzieli społeczeństwo na pół; kompromis lub głos wszystkich obywateli jest bezpieczniejszy niż rozstrzygnięcie jednej strony.', en: 'The dispute splits society in half; a compromise or a vote of all citizens is safer than one side winning.' },
        example: { pl: 'Kompromis z 1993 r. dopuszczał też aborcję przy ciężkiej wadzie płodu — do wyroku Trybunału w 2020 r.', en: 'The 1993 compromise also allowed abortion for severe foetal defects — until the Tribunal ruling in 2020.' },
        wiki: { pl: 'Aborcja w Polsce', en: 'Abortion in Poland' } },
      { camp: 'right', effects: { soc: 1, relig: 0.6 },
        text: { pl: 'Życie trzeba chronić od poczęcia — aborcja tylko przy zagrożeniu życia matki', en: 'Life must be protected from conception — abortion only when the mother\'s life is at risk' },
        why: { pl: 'Dziecko przed narodzeniem jest człowiekiem, a państwo ma obowiązek chronić najsłabszych.', en: 'An unborn child is a human being, and the state must protect the weakest.' },
        example: { pl: 'Malta przez lata zakazywała aborcji całkowicie; od 2023 r. tylko przy zagrożeniu życia kobiety.', en: 'Malta banned abortion entirely for years; since 2023 only when the woman\'s life is at risk.' },
        wiki: { pl: 'Ruch antyaborcyjny', en: 'Anti-abortion movements' } }
    ] },

  { id: 'x_cannabis', type: 'positions',
    text: { pl: 'Co z marihuaną?', en: 'What about cannabis?' },
    what: { pl: 'W Polsce posiadanie nawet niewielkiej ilości jest przestępstwem; od 2017 r. legalna jest marihuana medyczna na receptę.', en: 'In Poland possessing even a small amount is a crime; since 2017 medical cannabis has been legal on prescription.' },
    options: [
      { camp: 'left', effects: { soc: -0.8, just: -0.5 },
        text: { pl: 'Zalegalizować i sprzedawać legalnie pod kontrolą państwa', en: 'Legalise it and sell it legally under state control' },
        why: { pl: 'Zakaz napędza czarny rynek; legalny towar jest bezpieczniejszy, a podatek można wydać na profilaktykę.', en: 'The ban fuels the black market; a legal product is safer, and the tax can fund prevention.' },
        example: { pl: 'Kanada zalegalizowała marihuanę w 2018 r., a Niemcy częściowo w 2024 r.', en: 'Canada legalised cannabis in 2018, and Germany partly did in 2024.' },
        wiki: { pl: 'Legalność marihuany', en: 'Legality of cannabis' } },
      { camp: 'center', effects: { soc: -0.3, just: -0.4 },
        text: { pl: 'Nie karać za małe ilości na własny użytek, ale nie zezwalać na handel', en: 'Do not punish small amounts for personal use, but keep selling illegal' },
        why: { pl: 'Więzienie za jointa niszczy młodym ludziom życie, a policja ma ważniejsze sprawy.', en: 'Prison for a joint wrecks young lives, and the police have more important things to do.' },
        example: { pl: 'Portugalia w 2001 r. przestała karać za posiadanie narkotyków i kieruje ludzi na terapię.', en: 'In 2001 Portugal stopped punishing drug possession and refers people to treatment instead.' },
        wiki: { pl: 'Dekryminalizacja', en: 'Drug policy of Portugal' } },
      { camp: 'right_cons', effects: { soc: 0.8, just: 0.6 },
        text: { pl: 'Utrzymać zakaz — to droga do cięższych narkotyków', en: 'Keep the ban — it is a gateway to harder drugs' },
        why: { pl: 'Legalizacja wysyła młodzieży sygnał, że to nic złego, i zwiększa liczbę uzależnionych.', en: 'Legalisation tells young people it is harmless and increases addiction.' },
        example: { pl: 'Japonia i Singapur surowo karzą za posiadanie i mają bardzo niskie spożycie.', en: 'Japan and Singapore punish possession harshly and have very low use.' },
        wiki: { pl: 'Narkotyki', en: 'War on drugs' } },
      { camp: 'right_free', effects: { soc: -0.4, econ: 0.6, power: -0.4 },
        text: { pl: 'Zalegalizować, bo dorosły sam decyduje, co robi ze swoim ciałem', en: 'Legalise it, because adults decide for themselves what they do with their bodies' },
        why: { pl: 'Państwo nie jest od wychowywania dorosłych; wolny rynek wyprze dilerów lepiej niż policja.', en: 'The state is not there to raise adults; a free market will drive out dealers better than the police.' },
        example: { pl: 'Część amerykańskich stanów zalegalizowała marihuanę w referendach, np. Kolorado w 2012 r.', en: 'Several US states legalised cannabis in referendums, e.g. Colorado in 2012.' },
        wiki: { pl: 'Libertarianizm', en: 'Libertarianism' } }
    ] },

  { id: 'x_sexed', type: 'positions',
    text: { pl: 'Czego szkoła powinna uczyć o seksualności i relacjach?', en: 'What should school teach about sexuality and relationships?' },
    what: { pl: 'Od 2025 r. w polskich szkołach jest przedmiot edukacja zdrowotna (z możliwością rezygnacji); wcześniej było wychowanie do życia w rodzinie.', en: 'Since 2025 Polish schools have had a health education subject (with an opt-out); before that there was "education for family life".' },
    options: [
      { camp: 'left', effects: { soc: -0.9 },
        text: { pl: 'Obowiązkowa, pełna edukacja seksualna: antykoncepcja, zgoda, orientacja', en: 'Compulsory, comprehensive sex education: contraception, consent, orientation' },
        why: { pl: 'Rzetelna wiedza chroni przed przemocą, chorobami i niechcianą ciążą lepiej niż milczenie.', en: 'Accurate knowledge protects against abuse, disease and unwanted pregnancy better than silence.' },
        example: { pl: 'Holandia — edukacja seksualna jest obowiązkowa od podstawówki, a nastoletnie ciąże należą do najrzadszych w Europie.', en: 'The Netherlands — sex education is compulsory from primary school, and teenage pregnancy is among the rarest in Europe.' },
        wiki: { pl: 'Edukacja seksualna', en: 'Sex education' } },
      { camp: 'center', effects: { soc: -0.2 },
        text: { pl: 'Edukacja zdrowotna z wiedzą o ciele i relacjach, ale rodzice mogą dziecko wypisać', en: 'Health education covering the body and relationships, but parents may opt their child out' },
        why: { pl: 'Dzieci potrzebują wiedzy, a rodzice — poczucia, że mają wpływ na wychowanie.', en: 'Children need knowledge, and parents need to feel they have a say in their upbringing.' },
        example: { pl: 'Polska od września 2025 r. — edukacja zdrowotna jest przedmiotem nieobowiązkowym.', en: 'Poland from September 2025 — health education is an optional subject.' },
        wiki: { pl: 'Edukacja seksualna', en: 'Health education' } },
      { camp: 'right', effects: { soc: 0.9, relig: 0.3 },
        text: { pl: 'To sprawa rodziców; szkoła może uczyć o rodzinie, małżeństwie i odpowiedzialności', en: 'This is for parents; school may teach about family, marriage and responsibility' },
        why: { pl: 'Wychowanie w sferze intymnej należy do rodziców, a nie do państwa i zewnętrznych organizacji.', en: 'Upbringing in intimate matters belongs to parents, not to the state or outside organisations.' },
        example: { pl: 'Polskie „wychowanie do życia w rodzinie” od 1999 r. — rodzice mogą zrezygnować pisemnie.', en: 'Poland\'s "education for family life" since 1999 — parents can opt out in writing.' },
        wiki: { pl: 'Wychowanie do życia w rodzinie', en: 'Abstinence-only sex education' } }
    ] },

  // ───────── ŚWIAT ─────────
  { id: 'x_euro', type: 'positions',
    text: { pl: 'Czy Polska powinna przyjąć euro?', en: 'Should Poland adopt the euro?' },
    what: { pl: 'Polska zobowiązała się do tego, wchodząc do UE, ale nie podała terminu. Własna waluta daje własną politykę stóp procentowych.', en: 'Poland committed to it when joining the EU but set no date. A national currency means its own interest-rate policy.' },
    options: [
      { camp: 'left', effects: { world: -0.8 },
        text: { pl: 'Tak, możliwie szybko — to pełne członkostwo w Europie', en: 'Yes, as soon as possible — it means full membership of Europe' },
        why: { pl: 'Wspólna waluta ułatwia handel i podróże i daje Polsce głos w najważniejszych decyzjach strefy euro.', en: 'A common currency makes trade and travel easier and gives Poland a voice in the euro area\'s key decisions.' },
        example: { pl: 'Chorwacja przyjęła euro w 2023 r., Słowacja w 2009 r.', en: 'Croatia adopted the euro in 2023, Slovakia in 2009.' },
        wiki: { pl: 'Euro', en: 'Euro' } },
      { camp: 'center', effects: { world: -0.2 },
        text: { pl: 'Tak, ale dopiero gdy płace i ceny zbliżą się do strefy euro', en: 'Yes, but only once wages and prices get closer to the euro area' },
        why: { pl: 'Zbyt wczesne przyjęcie grozi skokiem cen i utratą konkurencyjności, jak w niektórych krajach południa.', en: 'Adopting it too early risks price jumps and lost competitiveness, as in some southern countries.' },
        example: { pl: 'Czechy i Szwecja też formalnie mają przyjąć euro, ale nie spieszą się z tym.', en: 'Czechia and Sweden are also formally meant to adopt the euro but are in no hurry.' },
        wiki: { pl: 'Kryteria konwergencji', en: 'Euro convergence criteria' } },
      { camp: 'right', effects: { world: 0.9 },
        text: { pl: 'Nie — złoty to nasza suwerenność', en: 'No — the złoty is our sovereignty' },
        why: { pl: 'Własna waluta pozwala reagować na kryzysy; w strefie euro o stopach decyduje Frankfurt.', en: 'A national currency allows a response to crises; in the euro area Frankfurt sets interest rates.' },
        example: { pl: 'W kryzysie 2008–2009 słabszy złoty pomógł polskim eksporterom, a Polska uniknęła recesji.', en: 'In the 2008–09 crisis a weaker złoty helped Polish exporters, and Poland avoided recession.' },
        wiki: { pl: 'Złoty', en: 'Polish złoty' } }
    ] },

  { id: 'x_trade', type: 'positions',
    text: { pl: 'Czy chronić polskich producentów przed tanim importem?', en: 'Should Polish producers be protected from cheap imports?' },
    what: { pl: 'Chodzi m.in. o umowę UE z Mercosurem (Ameryka Południowa) i o import zboża z Ukrainy.', en: 'This covers, for example, the EU deal with Mercosur (South America) and grain imports from Ukraine.' },
    options: [
      { camp: 'left', effects: { world: -0.2, econ: -0.6, eco: -0.3 },
        text: { pl: 'Handlować, ale tylko z krajami, które przestrzegają praw pracowników i norm ekologicznych', en: 'Trade, but only with countries that respect workers\' rights and environmental standards' },
        why: { pl: 'Tani import często bierze się z wyzysku i niszczenia przyrody; uczciwa konkurencja wymaga tych samych zasad.', en: 'Cheap imports often come from exploitation and environmental damage; fair competition needs the same rules.' },
        example: { pl: 'UE od 2027 r. ma zakazać importu produktów wytworzonych pracą przymusową.', en: 'From 2027 the EU is to ban imports of products made with forced labour.' },
        wiki: { pl: 'Sprawiedliwy handel', en: 'Fair trade' } },
      { camp: 'center', effects: { world: -0.6, econ: 0.3 },
        text: { pl: 'Wolny handel w ramach umów UE, z okresami przejściowymi dla wrażliwych branż', en: 'Free trade through EU agreements, with transition periods for sensitive sectors' },
        why: { pl: 'Eksport to siła polskiej gospodarki; lepiej chronić wybrane branże niż zamykać rynki.', en: 'Exports are the strength of the Polish economy; better to shield selected sectors than to close markets.' },
        example: { pl: 'Jednolity rynek UE — ponad 70% polskiego eksportu trafia do innych krajów Unii.', en: 'The EU single market — over 70% of Polish exports go to other EU countries.' },
        wiki: { pl: 'Jednolity rynek', en: 'European single market' } },
      { camp: 'right_cons', effects: { world: 0.8, econ: -0.2 },
        text: { pl: 'Tak — cła i zakazy importu, gdy zagraża on polskim rolnikom i firmom', en: 'Yes — tariffs and import bans when imports threaten Polish farmers and firms' },
        why: { pl: 'Własna żywność i przemysł to bezpieczeństwo; nie można dopuścić do upadku polskiej wsi.', en: 'Home-grown food and industry are security; Polish farming must not be allowed to collapse.' },
        example: { pl: 'Polska w 2023 r. jednostronnie zakazała importu zboża z Ukrainy po protestach rolników.', en: 'In 2023 Poland unilaterally banned grain imports from Ukraine after farmers\' protests.' },
        wiki: { pl: 'Protekcjonizm', en: 'Protectionism' } },
      { camp: 'right_free', effects: { world: -0.3, econ: 1 },
        text: { pl: 'Nie — wolny handel bez ceł, niech kupujący wybiera', en: 'No — free trade without tariffs, let buyers choose' },
        why: { pl: 'Cła płaci w końcu konsument, a ochrona przed konkurencją rozleniwia firmy.', en: 'Tariffs are ultimately paid by consumers, and protection from competition makes firms lazy.' },
        example: { pl: 'Singapur i Hongkong — niemal bez ceł, a są jednymi z najbogatszych miejsc świata.', en: 'Singapore and Hong Kong — almost no tariffs, and among the richest places in the world.' },
        wiki: { pl: 'Wolny handel', en: 'Free trade' } }
    ] },

  // ───────── EKOLOGIA ─────────
  { id: 'x_cars', type: 'positions',
    text: { pl: 'Czy stare auta spalinowe powinny mieć zakaz wjazdu do centrów miast?', en: 'Should old combustion cars be banned from city centres?' },
    what: { pl: 'Chodzi o strefy czystego transportu, które wprowadzają m.in. Warszawa i Kraków, by ograniczyć smog.', en: 'This is about clean transport zones, introduced by Warsaw and Kraków among others, to reduce smog.' },
    options: [
      { camp: 'left', effects: { eco: -0.9 },
        text: { pl: 'Tak, a do tego centra bez aut, z dobrą komunikacją publiczną', en: 'Yes, plus car-free centres with good public transport' },
        why: { pl: 'Spaliny szkodzą zdrowiu wszystkich, a miasto bez korków jest przyjaźniejsze do życia.', en: 'Exhaust fumes harm everyone\'s health, and a city without traffic jams is a better place to live.' },
        example: { pl: 'Pontevedra w Hiszpanii zamknęła centrum dla aut w 1999 r. i przyciąga turystów oraz mieszkańców.', en: 'Pontevedra in Spain closed its centre to cars in 1999 and now attracts tourists and residents.' },
        wiki: { pl: 'Deptak', en: 'Car-free zone' } },
      { camp: 'center', effects: { eco: -0.4 },
        text: { pl: 'Tak, ale stopniowo, z wyjątkami dla mieszkańców i biedniejszych kierowców', en: 'Yes, but gradually, with exemptions for residents and poorer drivers' },
        why: { pl: 'Czystsze powietrze jest ważne, ale nie można z dnia na dzień odciąć ludzi od dojazdu do pracy.', en: 'Cleaner air matters, but people cannot be cut off from getting to work overnight.' },
        example: { pl: 'Warszawa — strefa od 2024 r., a mieszkańcy ze starszymi autami mają kilka lat przejściowych.', en: 'Warsaw — a zone since 2024, with several transition years for residents with older cars.' },
        wiki: { pl: 'Strefa czystego transportu', en: 'Low-emission zone' } },
      { camp: 'right', effects: { eco: 0.8, econ: 0.3 },
        text: { pl: 'Nie — samochód to wolność, a zakazy uderzają w biedniejszych', en: 'No — the car is freedom, and bans hit poorer people' },
        why: { pl: 'Na nowe auto nie każdego stać; ludzie spoza miasta też muszą do niego dojechać.', en: 'Not everyone can afford a new car; people from outside the city also need to get into it.' },
        example: { pl: 'Kraków po protestach mieszkańców złagodził i odłożył w czasie swoją strefę.', en: 'After residents\' protests, Kraków softened and postponed its zone.' },
        wiki: { pl: 'Samochód osobowy', en: 'Car dependency' } }
    ] },

  { id: 'x_forest', type: 'positions',
    text: { pl: 'Co robić z lasami?', en: 'What should be done with forests?' },
    what: { pl: 'Większością polskich lasów zarządzają Lasy Państwowe, które sprzedają drewno. Spór: ile chronić, a ile wycinać.', en: 'Most Polish forests are managed by the State Forests, which sell timber. The dispute: how much to protect and how much to fell.' },
    options: [
      { camp: 'left', effects: { eco: -1 },
        text: { pl: 'Chronić dużo więcej — nowe parki narodowe, koniec wycinki starych lasów', en: 'Protect far more — new national parks, no more felling of old-growth forests' },
        why: { pl: 'Stary las to bogactwo przyrody, magazyn węgla i woda; nowe drzewka tego nie zastąpią przez 100 lat.', en: 'Old forest is a wealth of nature, a carbon store and water; young trees will not replace it for 100 years.' },
        example: { pl: 'Puszcza Białowieska — w 2018 r. unijny trybunał uznał jej masową wycinkę za niezgodną z prawem.', en: 'Białowieża Forest — in 2018 the EU court ruled its large-scale logging unlawful.' },
        wiki: { pl: 'Puszcza Białowieska', en: 'Białowieża Forest' } },
      { camp: 'center', effects: { eco: -0.4 },
        text: { pl: 'Wyłączyć z wycinki najcenniejsze lasy, a resztą gospodarować z umiarem', en: 'Exclude the most valuable forests from felling and manage the rest in moderation' },
        why: { pl: 'Drewno jest potrzebne i daje pracę, ale najcenniejsza przyroda powinna zostać nietknięta.', en: 'Timber is needed and provides jobs, but the most valuable nature should stay untouched.' },
        example: { pl: 'Od 2024 r. część polskich lasów przy miastach i o dużej wartości przyrodniczej wyłączono z wycinki.', en: 'Since 2024 some Polish forests near cities and of high natural value have been excluded from felling.' },
        wiki: { pl: 'Lasy Państwowe', en: 'State Forests (Poland)' } },
      { camp: 'right', effects: { eco: 0.8 },
        text: { pl: 'Las to zasób gospodarczy — o wycince powinni decydować leśnicy, nie aktywiści', en: 'The forest is an economic resource — foresters should decide on felling, not activists' },
        why: { pl: 'Polska ma dziś więcej lasów niż po wojnie właśnie dzięki leśnikom; drewno to praca dla tysięcy ludzi.', en: 'Poland has more forest today than after the war thanks to foresters; timber means work for thousands.' },
        example: { pl: 'Lesistość Polski wzrosła z ok. 21% w 1945 r. do ok. 30% dzisiaj.', en: 'Poland\'s forest cover rose from about 21% in 1945 to about 30% today.' },
        wiki: { pl: 'Gospodarka leśna', en: 'Forestry' } }
    ] },

  { id: 'x_flights', type: 'positions',
    text: { pl: 'Czy loty i inne „emisyjne” wygody powinny kosztować więcej ze względu na klimat?', en: 'Should flights and other high-emission comforts cost more because of the climate?' },
    what: { pl: 'Spór o to, kto ma płacić za ograniczanie emisji: najbogatsi, wszyscy czy nikt.', en: 'The dispute over who should pay for cutting emissions: the richest, everyone, or no one.' },
    options: [
      { camp: 'left', effects: { eco: -0.9, econ: -0.4 },
        text: { pl: 'Tak — wysokie podatki dla częstych pasażerów i zakaz krótkich lotów, gdy jest pociąg', en: 'Yes — high taxes on frequent flyers and a ban on short flights where there is a train' },
        why: { pl: 'Większość lotów odbywa niewielka grupa zamożnych ludzi; to oni powinni najbardziej płacić za emisje.', en: 'Most flights are taken by a small group of wealthy people; they should pay most for the emissions.' },
        example: { pl: 'Francja od 2023 r. zakazała lotów krajowych na trasach, które pociąg pokonuje w mniej niż 2,5 godziny.', en: 'Since 2023 France has banned domestic flights on routes a train covers in under 2.5 hours.' },
        wiki: { pl: 'Kolej dużych prędkości', en: 'Short-haul flight ban' } },
      { camp: 'center', effects: { eco: -0.4, world: -0.3 },
        text: { pl: 'Opłaty za emisje wspólne w całej UE, ale bez zakazów', en: 'EU-wide emission charges, but no bans' },
        why: { pl: 'Cena emisji zachęca do oszczędzania, a wspólne zasady nie karzą jednego kraju bardziej niż innych.', en: 'A price on emissions encourages savings, and common rules do not punish one country more than others.' },
        example: { pl: 'Unijny system handlu emisjami obejmuje loty w Europie od 2012 r.', en: 'The EU Emissions Trading System has covered flights within Europe since 2012.' },
        wiki: { pl: 'Europejski System Handlu Emisjami', en: 'European Union Emissions Trading System' } },
      { camp: 'right', effects: { eco: 0.8, world: 0.4 },
        text: { pl: 'Nie — żadnych nowych podatków klimatycznych, ludzie mają prawo podróżować', en: 'No — no new climate taxes, people have the right to travel' },
        why: { pl: 'Takie opłaty sprawiają, że podróże znów stają się luksusem dla bogatych, a emisje Polski i tak są małe wobec Chin.', en: 'Such charges make travel a luxury for the rich again, and Poland\'s emissions are small next to China\'s anyway.' },
        example: { pl: 'Protesty rolników w całej UE w 2024 r. wymusiły złagodzenie części przepisów Zielonego Ładu.', en: 'Farmers\' protests across the EU in 2024 forced parts of the Green Deal to be relaxed.' },
        wiki: { pl: 'Europejski Zielony Ład', en: 'European Green Deal' } }
    ] },

  // ───────── RELIGIA ─────────
  { id: 'x_schoolrel', type: 'positions',
    text: { pl: 'Czy religia powinna być w szkole?', en: 'Should religion be taught in school?' },
    what: { pl: 'Od 1990 r. lekcje religii odbywają się w polskich szkołach publicznych i płaci za nie państwo.', en: 'Since 1990, religion lessons have been held in Polish state schools and paid for by the state.' },
    options: [
      { camp: 'left', effects: { relig: -1 },
        text: { pl: 'Nie — katecheza do parafii, a w szkole lekcje o wielu religiach i etyce', en: 'No — catechism in parishes, and in school lessons on many religions and ethics' },
        why: { pl: 'Szkoła publiczna jest dla wszystkich i nie powinna uczyć jednej wiary za pieniądze podatników.', en: 'A state school is for everyone and should not teach one faith with taxpayers\' money.' },
        example: { pl: 'Francja — w szkołach publicznych od ponad stu lat nie ma lekcji religii.', en: 'France — state schools have had no religion lessons for over a century.' },
        wiki: { pl: 'Laicyzm', en: 'Laïcité' } },
      { camp: 'center', effects: { relig: -0.1 },
        text: { pl: 'Tak, ale dobrowolnie, raz w tygodniu, na pierwszej lub ostatniej lekcji', en: 'Yes, but voluntarily, once a week, in the first or last period' },
        why: { pl: 'Chętni mają łatwy dostęp do religii, a pozostali nie tracą czasu na okienkach.', en: 'Those who want it can easily attend, and others do not waste time in gaps between lessons.' },
        example: { pl: 'Polska — rozporządzenie z 2025 r. ograniczyło religię do jednej godziny tygodniowo.', en: 'Poland — a 2025 regulation cut religion to one hour a week.' },
        wiki: { pl: 'Katecheza', en: 'Catechesis' } },
      { camp: 'right', effects: { relig: 0.9, soc: 0.4 },
        text: { pl: 'Tak, dwie godziny i obowiązkowy wybór: religia albo etyka', en: 'Yes, two hours a week and a compulsory choice: religion or ethics' },
        why: { pl: 'Chrześcijaństwo ukształtowało polską kulturę; szkoła powinna przekazywać wartości, a nie tylko wiedzę.', en: 'Christianity shaped Polish culture; schools should pass on values, not just knowledge.' },
        example: { pl: 'Niemcy — w większości landów religia lub etyka to obowiązkowy przedmiot szkolny.', en: 'Germany — in most states religion or ethics is a compulsory school subject.' },
        wiki: { pl: 'Konkordat między Stolicą Apostolską i Rzecząpospolitą Polską (1993)', en: 'Religious education' } }
    ] },

  { id: 'x_churchfund', type: 'positions',
    text: { pl: 'Jak finansować Kościoły?', en: 'How should churches be funded?' },
    what: { pl: 'W Polsce działa Fundusz Kościelny, z którego budżet płaci m.in. składki emerytalne duchownych.', en: 'Poland has a Church Fund from which the state budget pays, among other things, clergy pension contributions.' },
    options: [
      { camp: 'left', effects: { relig: -1, econ: -0.2 },
        text: { pl: 'Tylko z datków wiernych — zlikwidować Fundusz Kościelny i przywileje podatkowe', en: 'Only from believers\' donations — abolish the Church Fund and tax privileges' },
        why: { pl: 'Państwo świeckie nie powinno finansować żadnej religii z pieniędzy wszystkich podatników.', en: 'A secular state should not fund any religion with all taxpayers\' money.' },
        example: { pl: 'USA — Kościoły utrzymują się z datków, bez pieniędzy z budżetu.', en: 'The USA — churches live on donations, with no money from the budget.' },
        wiki: { pl: 'Rozdział Kościoła od państwa', en: 'Separation of church and state' } },
      { camp: 'center', effects: { relig: -0.3 },
        text: { pl: 'Dobrowolny odpis od podatku — każdy decyduje, czy i komu przekaże część PIT', en: 'A voluntary tax allocation — everyone decides whether and to whom to give part of their income tax' },
        why: { pl: 'Kościół dostaje pieniądze tylko od tych, którzy tego chcą, a reszta może wesprzeć inny cel.', en: 'The church only gets money from those who want to give it, and others can support another cause.' },
        example: { pl: 'Włochy — obywatel przeznacza 0,8% podatku na wybrany Kościół albo na cele państwowe.', en: 'Italy — citizens assign 0.8% of their tax to a church of their choice or to state purposes.' },
        wiki: { pl: 'Fundusz Kościelny', en: 'Eight per thousand' } },
      { camp: 'right', effects: { relig: 0.8 },
        text: { pl: 'Utrzymać wsparcie — Kościół prowadzi szkoły, hospicja i chroni zabytki', en: 'Keep the support — the church runs schools and hospices and protects heritage' },
        why: { pl: 'To rekompensata za majątek odebrany przez komunistów i zapłata za pracę społeczną Kościoła.', en: 'It compensates for property seized by the communists and pays for the church\'s social work.' },
        example: { pl: 'Fundusz Kościelny powstał w 1950 r., po przejęciu przez państwo ziem kościelnych.', en: 'The Church Fund was set up in 1950, after the state seized church land.' },
        wiki: { pl: 'Caritas Polska', en: 'Church tax' } }
    ] },

  { id: 'x_blasphemy', type: 'positions',
    text: { pl: 'Czy obrażanie uczuć religijnych powinno być przestępstwem?', en: 'Should offending religious feelings be a crime?' },
    what: { pl: 'Polski kodeks karny (art. 196) przewiduje za to grzywnę, ograniczenie wolności, a nawet do 2 lat więzienia.', en: 'Polish criminal law (Article 196) punishes it with a fine, restricted liberty or up to 2 years in prison.' },
    options: [
      { camp: 'left', effects: { relig: -0.9, power: -0.4 },
        text: { pl: 'Nie — wolność słowa obejmuje też krytykę i żarty z religii', en: 'No — free speech includes criticising and joking about religion' },
        why: { pl: 'Uczucia są subiektywne; prawo nie może chronić idei przed krytyką, tylko ludzi przed przemocą.', en: 'Feelings are subjective; the law cannot shield ideas from criticism, only people from violence.' },
        example: { pl: 'Irlandia w 2018 r. w referendum usunęła przestępstwo bluźnierstwa z konstytucji.', en: 'In 2018 Ireland removed the offence of blasphemy from its constitution by referendum.' },
        wiki: { pl: 'Bluźnierstwo', en: 'Blasphemy law' } },
      { camp: 'center', effects: { relig: 0 },
        text: { pl: 'Karać tylko celowe znieważanie miejsc i obrzędów, np. zakłócanie mszy', en: 'Punish only deliberate desecration of places and ceremonies, e.g. disrupting a service' },
        why: { pl: 'Trzeba chronić prawo do spokojnego wyznawania wiary, ale nie zamykać ust krytykom.', en: 'The right to practise faith in peace must be protected, without silencing critics.' },
        example: { pl: 'Niemcy karzą obrazę wyznania tylko wtedy, gdy może zakłócić porządek publiczny.', en: 'Germany punishes insulting a faith only when it could disturb public order.' },
        wiki: { pl: 'Wolność wyznania', en: 'Freedom of religion' } },
      { camp: 'right', effects: { relig: 0.9, soc: 0.4 },
        text: { pl: 'Tak — i egzekwować to stanowczo, bo dla wierzących to sprawa najwyższej wagi', en: 'Yes — and enforce it firmly, because for believers this matters most' },
        why: { pl: 'Wolność słowa kończy się tam, gdzie zaczyna się szydzenie z tego, co dla milionów jest święte.', en: 'Free speech ends where mocking what is sacred to millions begins.' },
        example: { pl: 'W Polsce zapadały wyroki za obrazę uczuć religijnych, m.in. wobec znanych muzyków.', en: 'Polish courts have convicted people of offending religious feelings, including well-known musicians.' },
        wiki: { pl: 'Obraza uczuć religijnych', en: 'Blasphemy' } }
    ] },

  // ───────── BEZPIECZEŃSTWO ─────────
  { id: 'x_defense', type: 'positions',
    text: { pl: 'Ile Polska powinna wydawać na wojsko?', en: 'How much should Poland spend on defence?' },
    what: { pl: 'Polska wydaje dziś ok. 4,5% PKB, najwięcej w NATO. W 2025 r. NATO przyjęło cel 5% PKB do 2035 r.', en: 'Poland now spends about 4.5% of GDP, the most in NATO. In 2025 NATO set a target of 5% of GDP by 2035.' },
    options: [
      { camp: 'left', effects: { sec: -0.6, econ: -0.3 },
        text: { pl: 'Około 2% PKB wystarczy, resztę lepiej dać na zdrowie, szkoły i mieszkania', en: 'About 2% of GDP is enough; the rest is better spent on health, schools and housing' },
        why: { pl: 'Bezpieczeństwo to także silne społeczeństwo, a wyścig zbrojeń nikogo nie uspokaja.', en: 'Security also means a strong society, and an arms race reassures no one.' },
        example: { pl: 'Hiszpania na szczycie NATO w 2025 r. odmówiła zobowiązania się do celu 5% PKB.', en: 'At the 2025 NATO summit, Spain refused to commit to the 5% of GDP target.' },
        wiki: { pl: 'Państwo opiekuńcze', en: 'Guns versus butter model' } },
      { camp: 'center', effects: { sec: 0.4, world: -0.3 },
        text: { pl: 'Utrzymać ok. 4%, korzystając ze wspólnych funduszy UE i NATO', en: 'Keep about 4%, using joint EU and NATO funds' },
        why: { pl: 'Zagrożenie ze strony Rosji jest realne, ale razem z sojusznikami możemy wydawać rozsądniej.', en: 'The threat from Russia is real, but together with allies we can spend more sensibly.' },
        example: { pl: 'Unijny program pożyczek SAFE na zbrojenia z 2025 r. — Polska ma z niego najwięcej.', en: 'The EU\'s 2025 SAFE defence loan programme — Poland gets the most from it.' },
        wiki: { pl: 'Organizacja Traktatu Północnoatlantyckiego', en: 'NATO' } },
      { camp: 'right', effects: { sec: 1, world: 0.3 },
        text: { pl: '5% PKB i więcej — najsilniejsza armia lądowa w Europie', en: '5% of GDP or more — the strongest land army in Europe' },
        why: { pl: 'Pokój zapewnia tylko siła odstraszania; sojusznicy pomogą temu, kto sam umie się bronić.', en: 'Only deterrence keeps the peace; allies help those who can defend themselves.' },
        example: { pl: 'Izrael od lat wydaje na obronę kilka procent PKB i ma powszechny pobór.', en: 'Israel has spent several per cent of GDP on defence for years and has universal conscription.' },
        wiki: { pl: 'Siły Zbrojne Rzeczypospolitej Polskiej', en: 'Polish Armed Forces' } }
    ] },

  { id: 'x_guns', type: 'positions',
    text: { pl: 'Czy łatwiej powinno być kupić broń palną?', en: 'Should it be easier to buy a firearm?' },
    what: { pl: 'W Polsce trzeba zdać egzamin, przejść badania lekarskie i psychologiczne oraz mieć ważny powód, np. sport albo kolekcjonerstwo.', en: 'In Poland you must pass an exam, medical and psychological checks, and have a valid reason such as sport or collecting.' },
    options: [
      { camp: 'left', effects: { sec: -0.7, power: 0.2 },
        text: { pl: 'Nie — powinno być trudniej, mniej broni to mniej tragedii', en: 'No — it should be harder; fewer guns mean fewer tragedies' },
        why: { pl: 'Tam, gdzie broni jest dużo, częściej dochodzi do strzelanin, samobójstw i wypadków.', en: 'Where guns are common, shootings, suicides and accidents happen more often.' },
        example: { pl: 'Australia po masakrze w 1996 r. odkupiła i zniszczyła ponad 600 tys. sztuk broni.', en: 'After a 1996 massacre, Australia bought back and destroyed over 600,000 firearms.' },
        wiki: { pl: 'Prawo dostępu do broni', en: 'Gun control' } },
      { camp: 'center', effects: { sec: 0.1 },
        text: { pl: 'Zostawić obecne zasady: badania, egzamin i ważny powód', en: 'Keep the current rules: checks, an exam and a valid reason' },
        why: { pl: 'Odpowiedzialni ludzie mogą mieć broń, a kontrola eliminuje osoby niebezpieczne.', en: 'Responsible people can own guns, while checks keep out dangerous ones.' },
        example: { pl: 'Liczba pozwoleń w Polsce szybko rośnie, głównie sportowych, a przestępstw z legalną bronią jest bardzo mało.', en: 'The number of permits in Poland is rising fast, mostly for sport, and crimes with legal guns are very rare.' },
        wiki: { pl: 'Pozwolenie na broń', en: 'Gun laws in Poland' } },
      { camp: 'right', effects: { sec: 0.6, power: -0.5 },
        text: { pl: 'Tak — prawo do obrony z bronią w ręku dla każdego niekaranego obywatela', en: 'Yes — the right to armed self-defence for every law-abiding citizen' },
        why: { pl: 'Uzbrojeni obywatele są odporniejsi na przestępców i na najeźdźcę; wolny człowiek może się bronić.', en: 'Armed citizens are tougher for criminals and invaders; a free person can defend themselves.' },
        example: { pl: 'Czechy w 2021 r. wpisały do konstytucji prawo do obrony z użyciem broni.', en: 'In 2021 Czechia wrote the right to defend oneself with a weapon into its constitution.' },
        wiki: { pl: 'Prawo dostępu do broni', en: 'Right to keep and bear arms' } }
    ] },

  { id: 'x_ukraine', type: 'positions',
    text: { pl: 'Jak Polska powinna pomagać Ukrainie?', en: 'How should Poland help Ukraine?' },
    what: { pl: 'Od rosyjskiej inwazji w 2022 r. Polska przekazała Ukrainie broń, przyjęła uchodźców i jest głównym szlakiem dostaw.', en: 'Since Russia\'s 2022 invasion, Poland has sent Ukraine weapons, taken in refugees and become the main supply route.' },
    options: [
      { camp: 'left', effects: { sec: -0.4, world: -0.5 },
        text: { pl: 'Wspierać, ale przede wszystkim humanitarnie i naciskać na rozmowy pokojowe', en: 'Support it, but mainly with humanitarian aid, and push for peace talks' },
        why: { pl: 'Każdy miesiąc wojny to tysiące ofiar; potrzebna jest pomoc ludziom i dyplomacja, a nie tylko broń.', en: 'Every month of war costs thousands of lives; people need aid and diplomacy, not only weapons.' },
        example: { pl: 'Polska przyjęła po 2022 r. ponad milion uchodźców z Ukrainy.', en: 'After 2022 Poland took in over a million refugees from Ukraine.' },
        wiki: { pl: 'Ukraiński kryzys uchodźczy', en: 'Ukrainian refugee crisis' } },
      { camp: 'center', effects: { sec: 0.6, world: -0.6 },
        text: { pl: 'Wspierać bronią i pieniędzmi, razem z UE i NATO — Ukraina broni też nas', en: 'Support it with weapons and money, together with the EU and NATO — Ukraine defends us too' },
        why: { pl: 'Jeśli Rosja wygra, następne mogą być Polska i kraje bałtyckie; taniej pomóc dziś niż walczyć jutro.', en: 'If Russia wins, Poland and the Baltics could be next; helping now is cheaper than fighting later.' },
        example: { pl: 'Polska była jednym z pierwszych krajów, które przekazały Ukrainie czołgi.', en: 'Poland was among the first countries to send Ukraine tanks.' },
        wiki: { pl: 'Inwazja Rosji na Ukrainę', en: 'Russian invasion of Ukraine' } },
      { camp: 'right', effects: { sec: 0.4, world: 0.7 },
        text: { pl: 'Pomagać, ale stawiać warunki w interesie Polski: zboże, Wołyń, transport', en: 'Help, but set conditions in Poland\'s interest: grain, Volhynia, transport' },
        why: { pl: 'Pomoc nie może być bezwarunkowa; Polska musi chronić swoich rolników i przewoźników i pamiętać o historii.', en: 'Help cannot be unconditional; Poland must protect its farmers and hauliers and remember history.' },
        example: { pl: 'Spór o ekshumacje ofiar rzezi wołyńskiej był jednym z warunków stawianych Ukrainie przez polskich polityków.', en: 'The dispute over exhuming victims of the Volhynia massacre was one of the conditions Polish politicians set for Ukraine.' },
        wiki: { pl: 'Rzeź wołyńska', en: 'Massacres of Poles in Volhynia and Eastern Galicia' } }
    ] },

  // ───────── SPRAWIEDLIWOŚĆ ─────────
  { id: 'x_death', type: 'positions',
    text: { pl: 'Czy przywrócić karę śmierci?', en: 'Should the death penalty be brought back?' },
    what: { pl: 'Polska zniosła karę śmierci w 1998 r. W UE jest zakazana, a jej przywrócenie oznaczałoby wyjście z Unii i Rady Europy.', en: 'Poland abolished the death penalty in 1998. It is banned in the EU, and restoring it would mean leaving the Union and the Council of Europe.' },
    options: [
      { camp: 'left', effects: { just: -1 },
        text: { pl: 'Nie, a nawet dożywocie powinno dawać szansę na zwolnienie po wielu latach', en: 'No, and even a life sentence should allow a chance of release after many years' },
        why: { pl: 'Państwo nie powinno zabijać; każdy wymiar sprawiedliwości się myli, a kary nie da się cofnąć.', en: 'The state should not kill; every justice system makes mistakes, and an execution cannot be undone.' },
        example: { pl: 'Norwegia — najwyższa kara to 21 lat, z możliwością przedłużenia, gdy sprawca nadal jest groźny.', en: 'Norway — the maximum sentence is 21 years, extendable if the offender is still dangerous.' },
        wiki: { pl: 'Kara śmierci', en: 'Capital punishment debate' } },
      { camp: 'center', effects: { just: 0.3 },
        text: { pl: 'Nie, ale za najcięższe zbrodnie dożywocie bez prawa do zwolnienia', en: 'No, but life without parole for the worst crimes' },
        why: { pl: 'Społeczeństwo musi być chronione przed najgroźniejszymi, bez ryzyka stracenia niewinnego.', en: 'Society must be protected from the most dangerous, without the risk of executing the innocent.' },
        example: { pl: 'Polski kodeks karny pozwala sądowi orzec dożywocie bez prawa do warunkowego zwolnienia.', en: 'The Polish criminal code lets courts impose life without the possibility of parole.' },
        wiki: { pl: 'Dożywotnie pozbawienie wolności', en: 'Life imprisonment' } },
      { camp: 'right', effects: { just: 1, world: 0.3 },
        text: { pl: 'Tak — za zabójstwa z premedytacją i zbrodnie na dzieciach', en: 'Yes — for premeditated murder and crimes against children' },
        why: { pl: 'Za najstraszniejsze zbrodnie należy się najwyższa kara; tego wymaga sprawiedliwość wobec ofiar.', en: 'The most terrible crimes deserve the ultimate punishment; justice for victims demands it.' },
        example: { pl: 'USA — kara śmierci obowiązuje w części stanów, m.in. w Teksasie i na Florydzie.', en: 'The USA — the death penalty applies in some states, including Texas and Florida.' },
        wiki: { pl: 'Kara śmierci', en: 'Capital punishment' } }
    ] },

  { id: 'x_juvenile', type: 'positions',
    text: { pl: 'Jak traktować nastolatków, którzy popełnią poważne przestępstwo?', en: 'How should teenagers who commit serious crimes be treated?' },
    what: { pl: 'W Polsce sprawcy do 17 lat trafiają zwykle przed sąd rodzinny; za najcięższe czyny 15-latek może odpowiadać jak dorosły.', en: 'In Poland offenders under 17 usually go to family court; for the worst offences a 15-year-old can be tried as an adult.' },
    options: [
      { camp: 'left', effects: { just: -0.9 },
        text: { pl: 'Terapia, ośrodki wychowawcze i praca z rodziną zamiast więzienia', en: 'Therapy, youth centres and work with the family instead of prison' },
        why: { pl: 'Mózg nastolatka jeszcze się rozwija; więzienie robi z młodego człowieka zawodowego przestępcę.', en: 'A teenager\'s brain is still developing; prison turns young people into career criminals.' },
        example: { pl: 'Finlandia — nastolatki trafiają do więzień bardzo rzadko, zamiast tego pracują z nimi opiekunowie.', en: 'Finland — teenagers are very rarely jailed; social workers work with them instead.' },
        wiki: { pl: 'Resocjalizacja', en: 'Juvenile delinquency' } },
      { camp: 'center', effects: { just: 0.1 },
        text: { pl: 'Zostawić obecny system: sąd rodzinny, a za zbrodnie sąd jak dla dorosłych', en: 'Keep the current system: family court, and adult court for the gravest crimes' },
        why: { pl: 'Zwykle wystarcza wychowanie, ale przy zabójstwie trzeba ochronić społeczeństwo i ofiary.', en: 'Correction is usually enough, but murder requires protecting society and victims.' },
        example: { pl: 'Polski kodeks karny (art. 10) pozwala sądzić 15-latka jak dorosłego za m.in. zabójstwo.', en: 'Poland\'s criminal code (Article 10) allows a 15-year-old to be tried as an adult for murder, among others.' },
        wiki: { pl: 'Prawo karne nieletnich', en: 'Age of criminal responsibility' } },
      { camp: 'right', effects: { just: 0.9 },
        text: { pl: 'Obniżyć wiek odpowiedzialności — poważna zbrodnia to poważna kara, bez względu na wiek', en: 'Lower the age of responsibility — a serious crime means serious punishment, whatever the age' },
        why: { pl: 'Młodzi przestępcy wiedzą, że niewiele im grozi; surowe kary odstraszają i chronią ofiary.', en: 'Young offenders know they risk little; tough punishment deters and protects victims.' },
        example: { pl: 'Rząd Szwecji zaproponował w 2025 r. obniżenie wieku odpowiedzialności karnej za najcięższe przestępstwa z 15 do 13 lat.', en: 'In 2025 the Swedish government proposed lowering the age of criminal responsibility for the most serious crimes from 15 to 13.' },
        wiki: { pl: 'Przestępczość nieletnich', en: 'Youth crime' } }
    ] },

  { id: 'x_prison', type: 'positions',
    text: { pl: 'Czemu przede wszystkim ma służyć więzienie?', en: 'What is prison mainly for?' },
    what: { pl: 'Kara, odstraszanie, odizolowanie groźnych ludzi czy przygotowanie do powrotu na wolność.', en: 'Punishment, deterrence, isolating dangerous people, or preparing them to return to society.' },
    options: [
      { camp: 'left', effects: { just: -1 },
        text: { pl: 'Przygotowaniu do normalnego życia: nauka zawodu, terapia, kontakt z rodziną', en: 'Preparing for normal life: job training, therapy, contact with family' },
        why: { pl: 'Prawie każdy więzień kiedyś wyjdzie; lepiej, żeby wyszedł z zawodem, a nie z nowymi kontaktami w półświatku.', en: 'Almost every prisoner gets out one day; better with a trade than with new underworld contacts.' },
        example: { pl: 'Norwegia — więzienie Halden przypomina akademik, a odsetek powrotów do przestępstwa jest jednym z najniższych na świecie.', en: 'Norway — Halden prison resembles a dormitory, and reoffending is among the lowest in the world.' },
        wiki: { pl: 'Resocjalizacja', en: 'Halden Prison' } },
      { camp: 'center', effects: { just: 0.1 },
        text: { pl: 'Karze i resocjalizacji naraz, a za drobne czyny lepsze prace społeczne i dozór elektroniczny', en: 'Both punishment and rehabilitation, with community service and electronic tags for minor offences' },
        why: { pl: 'Groźnych trzeba odizolować, ale zamykanie drobnych sprawców kosztuje i niewiele daje.', en: 'Dangerous people must be isolated, but locking up petty offenders is costly and achieves little.' },
        example: { pl: 'W Polsce kilka tysięcy osób odbywa karę w domu z opaską elektroniczną.', en: 'In Poland several thousand people serve sentences at home with an electronic tag.' },
        wiki: { pl: 'System dozoru elektronicznego', en: 'Electronic tagging' } },
      { camp: 'right', effects: { just: 1 },
        text: { pl: 'Karze — ma być dotkliwe, żeby odstraszało', en: 'Punishment — it should be harsh so that it deters' },
        why: { pl: 'Przestępca odebrał coś ofierze; więzienie nie może być wygodniejsze niż życie uczciwie pracujących ludzi.', en: 'The offender took something from the victim; prison must not be more comfortable than honest working life.' },
        example: { pl: 'Kalifornia w 1994 r. przyjęła zasadę „trzech przewinień”: trzecie poważne przestępstwo oznaczało nawet dożywocie.', en: 'In 1994 California adopted "three strikes": a third serious felony could mean life in prison.' },
        wiki: { pl: 'Zakład karny', en: 'Three-strikes law' } }
    ] },

  // ───────── TECHNOLOGIA ─────────
  { id: 'x_nuclear', type: 'positions',
    text: { pl: 'Czy Polska powinna budować elektrownie jądrowe?', en: 'Should Poland build nuclear power plants?' },
    what: { pl: 'Pierwsza polska elektrownia jądrowa ma powstać na Pomorzu, w gminie Choczewo, w latach 30.', en: 'Poland\'s first nuclear plant is due to be built in Pomerania, in Choczewo municipality, in the 2030s.' },
    options: [
      { camp: 'left', effects: { tech: -0.6, eco: -0.5 },
        text: { pl: 'Raczej nie — taniej i szybciej postawić na wiatr, słońce i magazyny energii', en: 'Rather not — wind, solar and storage are cheaper and faster' },
        why: { pl: 'Atom buduje się kilkanaście lat i drożeje po drodze, a problem odpadów nie jest rozwiązany.', en: 'Nuclear takes over a decade to build and gets pricier along the way, and the waste problem is unsolved.' },
        example: { pl: 'Niemcy zamknęły ostatnie reaktory w kwietniu 2023 r.', en: 'Germany shut down its last reactors in April 2023.' },
        wiki: { pl: 'Odnawialne źródła energii', en: 'Renewable energy' } },
      { camp: 'center', effects: { tech: 0.4, eco: -0.3 },
        text: { pl: 'Tak, razem z odnawialnymi źródłami — atom jako stabilna podstawa', en: 'Yes, together with renewables — nuclear as a stable base' },
        why: { pl: 'Wiatr i słońce nie zawsze świecą; atom daje stały prąd bez emisji.', en: 'The wind does not always blow nor the sun shine; nuclear provides steady power with no emissions.' },
        example: { pl: 'Finlandia uruchomiła w 2023 r. reaktor Olkiluoto 3 i rozwija też farmy wiatrowe.', en: 'Finland started the Olkiluoto 3 reactor in 2023 and is also building wind farms.' },
        wiki: { pl: 'Energetyka jądrowa w Polsce', en: 'Nuclear power in Poland' } },
      { camp: 'right', effects: { tech: 0.7, eco: 0.5, world: 0.3 },
        text: { pl: 'Tak, jak najwięcej i jak najszybciej, a do tego czasu węgiel i gaz', en: 'Yes, as many as possible as fast as possible, with coal and gas until then' },
        why: { pl: 'Tani i pewny prąd to podstawa przemysłu i niezależności od Rosji czy kaprysów pogody.', en: 'Cheap, reliable power is the basis of industry and independence from Russia or the weather.' },
        example: { pl: 'Francja ma ok. 70% prądu z elektrowni jądrowych i jeden z najczystszych miksów w Europie.', en: 'France gets about 70% of its electricity from nuclear and has one of Europe\'s cleanest power mixes.' },
        wiki: { pl: 'Elektrownia jądrowa', en: 'Nuclear power in France' } }
    ] },

  { id: 'x_kidsonline', type: 'positions',
    text: { pl: 'Czy dzieci poniżej 16 lat powinny mieć zakaz korzystania z mediów społecznościowych?', en: 'Should children under 16 be banned from social media?' },
    what: { pl: 'Coraz więcej badań łączy media społecznościowe z gorszym zdrowiem psychicznym nastolatków. Kraje szukają rozwiązań.', en: 'More and more research links social media to poorer teenage mental health. Countries are looking for answers.' },
    options: [
      { camp: 'left', effects: { tech: -0.6, econ: -0.4 },
        text: { pl: 'Zamiast zakazu dla dzieci — twarde zasady dla platform: koniec uzależniających algorytmów i reklam', en: 'Instead of banning children — strict rules for platforms: no addictive algorithms or ads' },
        why: { pl: 'Winne są firmy, które zarabiają na uzależnianiu; to je trzeba kontrolować, a nie karać dzieci.', en: 'The blame lies with companies that profit from addiction; they must be controlled, not children punished.' },
        example: { pl: 'Unijny akt o usługach cyfrowych (DSA) zakazuje platformom reklam profilowanych dla dzieci.', en: 'The EU Digital Services Act bans platforms from showing profiled ads to children.' },
        wiki: { pl: 'Akt o usługach cyfrowych', en: 'Digital Services Act' } },
      { camp: 'center', effects: { tech: -0.3 },
        text: { pl: 'Tak, z weryfikacją wieku — jak przy alkoholu', en: 'Yes, with age checks — like alcohol' },
        why: { pl: 'Dzieci nie radzą sobie z presją i hejtem w sieci; jasna granica wieku pomaga rodzicom.', en: 'Children cannot cope with online pressure and hate; a clear age limit helps parents.' },
        example: { pl: 'Australia od grudnia 2025 r. zakazuje kont w mediach społecznościowych osobom poniżej 16 lat.', en: 'Since December 2025 Australia has banned social media accounts for under-16s.' },
        wiki: { pl: 'Media społecznościowe', en: 'Social media age verification laws' } },
      { camp: 'right_cons', effects: { tech: -0.5, soc: 0.5 },
        text: { pl: 'Tak, a w szkołach także zakaz telefonów — dzieci potrzebują dzieciństwa, nie ekranu', en: 'Yes, and also ban phones in schools — children need a childhood, not a screen' },
        why: { pl: 'Telefon zastąpił zabawę, rozmowę i rodzinę; obowiązkiem dorosłych jest chronić dzieci.', en: 'Phones have replaced play, conversation and family; adults have a duty to protect children.' },
        example: { pl: 'Francja i Holandia zakazały korzystania z telefonów w szkołach.', en: 'France and the Netherlands have banned phone use in schools.' },
        wiki: { pl: 'Uzależnienie od internetu', en: 'Problematic smartphone use' } },
      { camp: 'right_free', effects: { tech: 0.6, power: -0.5 },
        text: { pl: 'Nie — to decyzja rodziców, nie państwa', en: 'No — this is for parents to decide, not the state' },
        why: { pl: 'Weryfikacja wieku oznacza pokazywanie dowodu w internecie, czyli koniec anonimowości dla wszystkich.', en: 'Age checks mean showing ID online, which ends anonymity for everyone.' },
        example: { pl: 'Organizacje broniące prywatności krytykują australijski zakaz za zbieranie danych o wszystkich użytkownikach.', en: 'Privacy groups criticise the Australian ban for collecting data on all users.' },
        wiki: { pl: 'Anonimowość', en: 'Internet privacy' } }
    ] },

  { id: 'x_cash', type: 'positions',
    text: { pl: 'Co z gotówką?', en: 'What about cash?' },
    what: { pl: 'Coraz więcej płacimy kartą i telefonem. Część sklepów i urzędów nie chce już przyjmować gotówki.', en: 'We pay more and more by card and phone. Some shops and offices no longer want to accept cash.' },
    options: [
      { camp: 'left', effects: { tech: 0.7, econ: -0.3, power: 0.2 },
        text: { pl: 'Odchodzić od gotówki — płatności cyfrowe ograniczają szarą strefę', en: 'Move away from cash — digital payments shrink the grey economy' },
        why: { pl: 'Gotówka ułatwia unikanie podatków i pranie pieniędzy; płatności elektroniczne są wygodne i przejrzyste.', en: 'Cash makes tax evasion and money laundering easier; electronic payments are convenient and transparent.' },
        example: { pl: 'Szwecja — gotówką płaci się już tylko przy kilku procentach zakupów.', en: 'Sweden — only a few per cent of purchases are now paid in cash.' },
        wiki: { pl: 'Pieniądz bezgotówkowy', en: 'Cashless society' } },
      { camp: 'center', effects: { tech: 0 },
        text: { pl: 'Jedno i drugie — sklepy i urzędy muszą przyjmować gotówkę', en: 'Both — shops and public offices must accept cash' },
        why: { pl: 'Seniorzy i ludzie bez konta nie mogą zostać wykluczeni, a gotówka działa nawet bez prądu i internetu.', en: 'Older people and those without a bank account must not be excluded, and cash works even without power or internet.' },
        example: { pl: 'Komisja Europejska zaproponowała w 2023 r. prawo, by sklepy w strefie euro co do zasady musiały przyjmować gotówkę.', en: 'In 2023 the European Commission proposed a law requiring shops in the euro area to accept cash as a rule.' },
        wiki: { pl: 'Gotówka', en: 'Cash' } },
      { camp: 'right', effects: { tech: -0.5, power: -0.7 },
        text: { pl: 'Zapisać prawo do gotówki w konstytucji — to wolność i prywatność', en: 'Write the right to cash into the constitution — it is freedom and privacy' },
        why: { pl: 'Bez gotówki państwo i banki widzą każdy zakup i mogą odciąć człowieka od jego pieniędzy.', en: 'Without cash, the state and banks see every purchase and can cut a person off from their money.' },
        example: { pl: 'Słowacja w 2023 r. wpisała prawo do płacenia gotówką do konstytucji.', en: 'In 2023 Slovakia wrote the right to pay in cash into its constitution.' },
        wiki: { pl: 'Prywatność', en: 'Financial privacy' } }
    ] },

  // ───────── SAMORZĄD ─────────
  { id: 'x_localtax', type: 'positions',
    text: { pl: 'Kto powinien decydować o podatkach i wydatkach w gminie?', en: 'Who should decide on taxes and spending in a municipality?' },
    what: { pl: 'Polskie gminy żyją głównie z udziału w PIT i CIT oraz z dotacji; same ustalają tylko niektóre podatki, np. od nieruchomości.', en: 'Polish municipalities live mainly on a share of income taxes and on grants; they set only some taxes themselves, e.g. property tax.' },
    options: [
      { camp: 'left', effects: { local: 0.2, econ: -0.7 },
        text: { pl: 'Państwo ma wyrównywać różnice — bogate gminy dzielą się z biednymi', en: 'The state should even out differences — rich municipalities share with poor ones' },
        why: { pl: 'Dziecko z małej wsi powinno mieć taką samą szkołę i autobus jak dziecko z bogatego miasta.', en: 'A child from a small village should have the same school and bus as one from a rich city.' },
        example: { pl: 'Polskie „janosikowe” — najbogatsze samorządy oddają część dochodów na rzecz biedniejszych.', en: 'Poland\'s "Janosik tax" — the richest local governments hand over part of their income to poorer ones.' },
        wiki: { pl: 'Janosikowe', en: 'Fiscal equalization' } },
      { camp: 'center', effects: { local: -0.5 },
        text: { pl: 'Więcej podatków ma zostawać w gminie, a ona sama decyduje, na co je wyda', en: 'More tax should stay in the municipality, and it decides how to spend it' },
        why: { pl: 'Wójt i radni lepiej znają potrzeby mieszkańców niż urzędnik w Warszawie.', en: 'Mayors and councillors know residents\' needs better than an official in Warsaw.' },
        example: { pl: 'Reforma z 2024 r. zwiększyła udział gmin w podatkach i dała im więcej swobody w ich wydawaniu.', en: 'A 2024 reform increased municipalities\' share of taxes and gave them more freedom in spending them.' },
        wiki: { pl: 'Samorząd terytorialny w Polsce', en: 'Municipalities of Poland' } },
      { camp: 'right', effects: { local: -0.9, econ: 0.6 },
        text: { pl: 'Gminy same ustalają swoje podatki i konkurują o mieszkańców i firmy', en: 'Municipalities set their own taxes and compete for residents and businesses' },
        why: { pl: 'Konkurencja zmusza samorządy do oszczędności, a mieszkańcy mogą „głosować nogami”.', en: 'Competition forces local governments to save, and residents can "vote with their feet".' },
        example: { pl: 'Szwajcaria — kantony i gminy same ustalają znaczną część podatku dochodowego.', en: 'Switzerland — cantons and municipalities set a large part of income tax themselves.' },
        wiki: { pl: 'Kanton (Szwajcaria)', en: 'Cantons of Switzerland' } }
    ] },

  { id: 'x_curriculum', type: 'positions',
    text: { pl: 'Kto powinien decydować, czego uczą szkoły?', en: 'Who should decide what schools teach?' },
    what: { pl: 'W Polsce obowiązuje jedna podstawa programowa dla całego kraju, ustalana przez ministra edukacji.', en: 'Poland has one national core curriculum, set by the education minister.' },
    options: [
      { camp: 'left', effects: { local: 0.5, econ: -0.4 },
        text: { pl: 'Jeden program dla wszystkich, ustalany z nauczycielami i naukowcami', en: 'One curriculum for all, drawn up with teachers and scientists' },
        why: { pl: 'Wspólny program daje równe szanse dzieciom z każdego regionu i z każdej rodziny.', en: 'A common curriculum gives equal chances to children from every region and every family.' },
        example: { pl: 'Finlandia — krajowa podstawa i dobrze opłacani nauczyciele z dużą swobodą w metodach.', en: 'Finland — a national core and well-paid teachers with a lot of freedom in methods.' },
        wiki: { pl: 'Podstawa programowa', en: 'National curriculum' } },
      { camp: 'center', effects: { local: -0.3 },
        text: { pl: 'Krótka wspólna podstawa, a resztę wybierają szkoły i nauczyciele', en: 'A short common core, with the rest chosen by schools and teachers' },
        why: { pl: 'Minimum wspólnej wiedzy jest potrzebne, ale szkoła lepiej wie, czego potrzebują jej uczniowie.', en: 'A minimum of shared knowledge is needed, but each school knows best what its pupils need.' },
        example: { pl: 'Holandia — szkoły mają dużą swobodę w programie, a państwo sprawdza efekty egzaminami.', en: 'The Netherlands — schools have wide freedom over the curriculum, and the state checks results with exams.' },
        wiki: { pl: 'System oświaty w Polsce', en: 'Education in the Netherlands' } },
      { camp: 'right_cons', effects: { local: -0.5, soc: 0.6 },
        text: { pl: 'Najwięcej do powiedzenia powinni mieć rodzice, łącznie z prawem do edukacji domowej', en: 'Parents should have the most say, including the right to home-school' },
        why: { pl: 'To rodzice odpowiadają za wychowanie dzieci i powinni mieć wpływ na to, jakie wartości przekazuje szkoła.', en: 'Parents are responsible for raising children and should influence the values the school passes on.' },
        example: { pl: 'W Polsce z edukacji domowej korzysta już kilkadziesiąt tysięcy dzieci.', en: 'In Poland tens of thousands of children are now home-schooled.' },
        wiki: { pl: 'Edukacja domowa', en: 'Homeschooling' } },
      { camp: 'right_free', effects: { local: -0.6, econ: 0.8 },
        text: { pl: 'Bon oświatowy — pieniądze idą za uczniem do wybranej szkoły, także prywatnej', en: 'Education vouchers — the money follows the pupil to the school of their choice, including private ones' },
        why: { pl: 'Szkoły, które konkurują o uczniów, muszą się starać; rodzice wybierają najlepsze.', en: 'Schools competing for pupils have to try harder; parents choose the best.' },
        example: { pl: 'Szwecja od 1992 r. finansuje bonami także szkoły prywatne.', en: 'Since 1992 Sweden has funded private schools through vouchers too.' },
        wiki: { pl: 'Bon oświatowy', en: 'School voucher' } }
    ] },

  { id: 'x_partbudget', type: 'positions',
    text: { pl: 'Jak dużą część budżetu miasta powinni rozdzielać sami mieszkańcy?', en: 'How much of a city\'s budget should residents allocate themselves?' },
    what: { pl: 'Budżet obywatelski: mieszkańcy zgłaszają pomysły (park, ławki, zajęcia) i głosują nad nimi.', en: 'Participatory budgeting: residents propose ideas (a park, benches, classes) and vote on them.' },
    options: [
      { camp: 'left', effects: { local: -0.8, power: -0.4 },
        text: { pl: 'Dużą — nawet kilka procent budżetu, z naradami w każdej dzielnicy', en: 'A large share — even several per cent of the budget, with meetings in every district' },
        why: { pl: 'Ludzie, którzy sami decydują, bardziej dbają o swoją okolicę i bardziej ufają władzy.', en: 'People who decide for themselves take more care of their neighbourhood and trust those in power more.' },
        example: { pl: 'Porto Alegre w Brazylii od 1989 r. — mieszkańcy decydowali o dużej części inwestycji miasta.', en: 'Porto Alegre, Brazil, since 1989 — residents decided a large share of city investment.' },
        wiki: { pl: 'Budżet partycypacyjny', en: 'Participatory budgeting' } },
      { camp: 'center', effects: { local: -0.3 },
        text: { pl: 'Niewielką, jak dziś — to dobra szkoła zaangażowania, ale resztą zarządzają radni', en: 'A small share, as now — good practice in engagement, but councillors manage the rest' },
        why: { pl: 'Małe projekty mieszkańcy wybiorą dobrze, ale szpital czy obwodnica wymagają planowania.', en: 'Residents choose small projects well, but a hospital or bypass needs planning.' },
        example: { pl: 'W dużych polskich miastach budżet obywatelski jest obowiązkowy i wynosi co najmniej 0,5% wydatków.', en: 'In large Polish cities participatory budgeting is mandatory and is at least 0.5% of spending.' },
        wiki: { pl: 'Budżet obywatelski', en: 'Municipalities of Poland' } },
      { camp: 'right', effects: { local: 0.2, econ: 0.4 },
        text: { pl: 'Żadną — od tego są wybrani radni; lepiej obniżyć lokalne podatki', en: 'None — that is what elected councillors are for; better to lower local taxes' },
        why: { pl: 'Głosują głównie aktywiści z kilku osiedli; pieniądze lepiej zwrócić wszystkim mieszkańcom.', en: 'Mostly activists from a few neighbourhoods vote; the money is better returned to all residents.' },
        example: { pl: 'W wielu miastach w głosowaniu nad budżetem obywatelskim bierze udział tylko kilka procent mieszkańców.', en: 'In many cities only a few per cent of residents vote on the participatory budget.' },
        wiki: { pl: 'Rada gminy', en: 'Municipal council' } }
    ] },

  { id: 'x_regions', type: 'positions',
    text: { pl: 'Ile władzy powinny mieć województwa?', en: 'How much power should Poland\'s regions have?' },
    what: { pl: 'Polska jest państwem jednolitym: prawo stanowi Sejm, a województwa zarządzają m.in. funduszami UE i koleją regionalną.', en: 'Poland is a unitary state: the Sejm makes laws, and regions manage things like EU funds and regional rail.' },
    options: [
      { camp: 'left', effects: { local: -0.7, world: -0.3 },
        text: { pl: 'Dużo — regiony z własnymi sejmikami i szeroką autonomią, jak landy w Niemczech', en: 'A lot — regions with their own assemblies and wide autonomy, like German states' },
        why: { pl: 'Śląsk, Podhale czy Pomorze mają różne potrzeby i tożsamość; Warszawa nie musi o wszystkim decydować.', en: 'Silesia, Podhale and Pomerania have different needs and identities; Warsaw need not decide everything.' },
        example: { pl: 'Niemcy — landy same prowadzą szkoły, policję i mają własne parlamenty.', en: 'Germany — the states run their own schools and police and have their own parliaments.' },
        wiki: { pl: 'Kraj związkowy', en: 'States of Germany' } },
      { camp: 'center', effects: { local: -0.3 },
        text: { pl: 'Więcej pieniędzy i zadań dla województw, ale bez własnych ustaw', en: 'More money and tasks for regions, but no regional laws' },
        why: { pl: 'Decentralizacja się sprawdziła, ale prawo powinno być jedno dla całego kraju.', en: 'Decentralisation has worked, but the law should be the same for the whole country.' },
        example: { pl: 'Reforma z 1999 r. utworzyła 16 województw z samorządem — uznawana za jedną z udanych polskich reform.', en: 'The 1999 reform created 16 self-governing regions — seen as one of Poland\'s successful reforms.' },
        wiki: { pl: 'Województwo', en: 'Voivodeships of Poland' } },
      { camp: 'right', effects: { local: 0.8, world: 0.3 },
        text: { pl: 'Mniej — silny rząd centralny trzyma kraj w jedności', en: 'Less — a strong central government keeps the country united' },
        why: { pl: 'Autonomia regionów rodzi separatyzmy i dzieli wspólnotę narodową.', en: 'Regional autonomy breeds separatism and divides the national community.' },
        example: { pl: 'Hiszpania — dążenie Katalonii do niepodległości doprowadziło w 2017 r. do kryzysu konstytucyjnego.', en: 'Spain — Catalonia\'s push for independence led to a constitutional crisis in 2017.' },
        wiki: { pl: 'Państwo unitarne', en: 'Unitary state' } }
    ] }
]);
